                    sGetCodeFinal = sGetCodeOriginal.Replace("%Code%", ((SAPbouiCOM.EditText)oMatrixSN.Columns.Item("Col_02").Cells.Item(iLinea).Specific).Value);

                    oConsultaCode.DoQuery(sGetCodeFinal);

