                        oGeneralData.SetProperty("U_BO_XKC", ((SAPbouiCOM.EditText)oMatrixSN.Columns.Item("Col_4").Cells.Item(iLinea).Specific).Value);

                        oGeneralService.Update(oGeneralData);

