                                                DllFunciones.sendMessageBox(_sboapp, "Error al enviar el documento a la DIAN - Codigo de mensaje No. " + sResponseErrorCode + ", " + ResponseEnvio.Rows[0]["shortDescription"].ToString().Replace(",", "\n"));
